# Verify formula: for normalized input (r, c), output positions are determined by {c, c+3}
# Applied per row r

demo_norm_8s = [(0,1), (0,2), (1,0), (1,1), (1,2), (2,1)]
expected_demo_out = [(0,1), (0,2), (0,4), (0,5), (1,0), (1,1), (1,2), (1,3), (1,4), (1,5), (2,1), (2,4)]

print("=== Verifying formula on demo 1 ===")
computed_demo = set()
for r, c in demo_norm_8s:
    outs = {c, c+3}
    for oc in outs:
        if 0 <= oc < 6:
            computed_demo.add((r, oc))

print(f"Expected: {sorted(expected_demo_out)}")
print(f"Computed: {sorted(computed_demo)}")
print(f"Match: {sorted(expected_demo_out) == sorted(computed_demo)}")

# Now verify for test
test_norm_8s = [(0,0), (0,1), (1,0), (1,2), (2,0), (2,1)]
print("\n=== Computed test output ===")
computed_test = set()
for r, c in test_norm_8s:
    outs = {c, c+3}
    for oc in outs:
        if 0 <= oc < 6:
            computed_test.add((r, oc))

print(f"Test output cols by row:")
out_by_row = {}
for r, c in computed_test:
    out_by_row[r] = out_by_row.get(r, set()).union({c})
for r in sorted(out_by_row.keys()):
    print(f"  Row {r}: cols {sorted(out_by_row[r])}")

# This gives 12 8s which seems right!
grid = [[0]*6 for _ in range(3)]
for r, c in sorted(computed_test):
    grid[r][c] = 8
print("\nTest grid:")
for row in grid:
    print(" ".join(f"{x}" for x in row))
